const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];
const adj = Array.from({ length: n + 1 }, () => []);

let ptr = 1;
for (let i = 0; i < n - 1; i++) {
  const u = data[ptr++];
  const v = data[ptr++];
  adj[u].push(v);
  adj[v].push(u);
}

function farthest(start, keepParent) {
  const dist = new Int32Array(n + 1);
  dist.fill(-1);
  const parent = keepParent ? new Int32Array(n + 1) : null;
  const queue = new Int32Array(n + 1);

  let head = 0;
  let tail = 0;
  let far = start;
  let maxDist = 0;

  dist[start] = 0;
  queue[tail++] = start;

  while (head < tail) {
    const u = queue[head++];
    const du = dist[u];

    if (du > maxDist) {
      maxDist = du;
      far = u;
    }

    const list = adj[u];
    for (let i = 0; i < list.length; i++) {
      const v = list[i];
      if (dist[v] === -1) {
        dist[v] = du + 1;
        if (parent) parent[v] = u;
        queue[tail++] = v;
      }
    }
  }

  return { far, maxDist, parent };
}

const first = farthest(1, false);
const A = first.far;
const second = farthest(A, true);
const B = second.far;
const diameter = second.maxDist;
const parent = second.parent;

const path = [];
let cur = B;

while (cur !== 0) {
  path.push(cur);
  cur = parent[cur];
}

path.reverse();

function countAtDistance(root, forbidden, target) {
  if (target < 0) return 0;

  let count = 0;
  const stackNode = [root];
  const stackParent = [forbidden];
  const stackDepth = [0];

  while (stackNode.length > 0) {
    const u = stackNode.pop();
    const p = stackParent.pop();
    const depth = stackDepth.pop();

    if (depth === target) count++;

    if (depth < target) {
      const list = adj[u];
      for (let i = 0; i < list.length; i++) {
        const v = list[i];
        if (v !== p) {
          stackNode.push(v);
          stackParent.push(u);
          stackDepth.push(depth + 1);
        }
      }
    }
  }

  return count;
}

let answerCount;

if (diameter % 2 === 0) {
  const radius = diameter / 2;
  const center = path[radius];

  let total = 0;
  let sumSquares = 0;

  const list = adj[center];
  for (let i = 0; i < list.length; i++) {
    const branchCount = countAtDistance(list[i], center, radius - 1);
    total += branchCount;
    sumSquares += branchCount * branchCount;
  }

  answerCount = (total * total - sumSquares) / 2;
} else {
  const radius = Math.floor(diameter / 2);
  const c1 = path[radius];
  const c2 = path[radius + 1];

  const count1 = countAtDistance(c1, c2, radius);
  const count2 = countAtDistance(c2, c1, radius);

  answerCount = count1 * count2;
}

console.log(diameter + 1);
console.log(answerCount);
